// 概念示意：兩個提款操作各自的步驟
// 操作 A：讀 balance（100）→ 算出 100-30=70 → 寫回 70
// 操作 B：讀 balance（100）→ 算出 100-40=60 → 寫回 60

let balance = 100;

async function withdraw(amount) {
  const current = balance;
  await Promise.resolve();
  balance = current - amount;
}

async function main() {
  await Promise.all([withdraw(30), withdraw(40)]);
  console.log(balance);
}

main();

